from taf.sw.dcap.rd.interfaces.dcap_base import DCAP
from taf.sw.dcap.rd.schemas.cm.start_trace_v2 import StartTraceV2
from taf.sw.dcap.rd.auth.authorization import TokenProvider
from taf.sw.dcap.rd.services.cm.cm_v3 import CMv3
from taf.internal.sw.dcap.rd.client.dcap_lite.v3 import Configuration
from taf.sw.dcap.rd.services.decoder.decoder_v1 import Decoderv1
from taf.sw.dcap.rd.schemas.decoder.upload_result_info_v1 import UploadResultInfoV1
from taf.sw.dcap.rd.schemas.decoder.get_session_info_v1 import GetSessionInfoV1
from taf.sw.dcap.rd.schemas.cm.features_v1 import FeaturesV1


class DCAPv3(DCAP):
    cm = None

    def __init__(self, con_details, token=None):
        super(DCAPv3, self).__init__()
        self.token = token
        if token:
            self.cm = CMv3(con_details=con_details)
            self.decoder = Decoderv1(con_details=con_details)
            self.token_subscribers = [self.cm, self.decoder]
        else:
            conf = Configuration()
            conf.client_side_validation = True
            conf.verify_ssl = False
            conf.host = con_details.make_configuration_host(original_endpoint=conf.host)
            self.cm = CMv3(con_details=con_details)
            self.decoder = Decoderv1(con_details=con_details)

    @TokenProvider.provide_access_token
    def start_trace(self, bts, tag='start_trace', duration=-1, timeout=400, resource_group=None,
                    allow_start_failures=True, force=True, **kwargs):
        start_trace_body = self.cm.start_trace(bts=bts, tag=tag, duration=duration,
                                               timeout=timeout, resource_group=resource_group,
                                               allow_start_failures=allow_start_failures, force=force, **kwargs)
        return StartTraceV2.from_object_dict(data=start_trace_body)

    @TokenProvider.provide_access_token
    def check_precondition(self, invalidate_bts_info_cache=None, bts=None, timeout=400, **kwargs):
        return self.cm.check_precondition(invalidate_bts_info_cache=invalidate_bts_info_cache,
                                          bts=bts,
                                          timeout=timeout,
                                          **kwargs)

    @TokenProvider.provide_access_token
    def get_sacks(self, timeout):
        return self.decoder.get_sacks(timeout=timeout)

    @TokenProvider.provide_access_token
    def upload_sacks(self, file_name, timeout):
        return self.decoder.upload_sacks(file_name=file_name, timeout=timeout)

    @TokenProvider.provide_access_token
    def upload_encoded_file(self, file_name, profile, session_Id, username, timeout):
        upload_encoded_file = self.decoder.upload_encoded_file(file_name=file_name, profile=profile,
                                                               session_Id=session_Id,
                                                               username=username, timeout=timeout)
        return UploadResultInfoV1.from_object_dict(upload_encoded_file)

    @TokenProvider.provide_access_token
    def get_encoded_files_info(self, timeout=None):
        get_encoded_files_info = self.decoder.get_encoded_files_info(timeout=timeout)
        return list(map(GetSessionInfoV1.from_object_dict, get_encoded_files_info))

    @TokenProvider.provide_access_token
    def get_decoded_file_contents(self, session_id, id_value, what, timeout, **kwargs):
        return self.decoder.get_decoded_file_contents(session_id=session_id,
                                                      data_source_id=id_value,
                                                      what=what,
                                                      timeout=timeout,
                                                      **kwargs)

    @TokenProvider.provide_access_token
    def get_decoded_file_contents_in_json(self, session_id, data_source_id, what, timeout, **kwargs):
        return self.decoder.get_decoded_file_contents_in_json(session_id=session_id,
                                                              data_source_id=data_source_id,
                                                              what=what,
                                                              timeout=timeout,
                                                              **kwargs)

    @TokenProvider.provide_access_token
    def get_decoded_file_contents_in_csv(self, session_id, data_source_id, what, timeout, **kwargs):
        return self.decoder.get_decoded_file_contents_in_csv(session_id=session_id,
                                                             data_source_id=data_source_id,
                                                             what=what,
                                                             timeout=timeout,
                                                             **kwargs)

    @TokenProvider.provide_access_token
    def get_features(self, timeout):
        get_features = self.cm.get_features(timeout=timeout)
        return FeaturesV1.from_object_dict(get_features)

    def get_decoding_profile_info(self, timeout):
        return self.decoder.get_decoding_profile_info(timeout=timeout)

    def upload_decoding_profile(self, profile_name, profile_bases, profile_file_path, timeout):
        return self.decoder.upload_decoding_profile(profile_name=profile_name,
                                                    profile_bases=profile_bases,
                                                    profile_file_path=profile_file_path,
                                                    timeout=timeout)

    @TokenProvider.provide_access_token
    def list_session_files(self, session_id, keepalive, timeout):
        return self.decoder.list_session_files(session_id=session_id,
                                               keepalive=keepalive,
                                               timeout=timeout)

    @TokenProvider.provide_access_token
    def download_session_file(self, session_id, file_name, target_dir, timeout):
        return self.decoder.download_session_file(session_id=session_id,
                                                  file_name=file_name,
                                                  target_dir=target_dir,
                                                  timeout=timeout)

    @TokenProvider.provide_access_token
    def delete_session_data(self, session_id, timeout):
        return self.decoder.delete_session_data(session_id=session_id,
                                                timeout=timeout)
